import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Euler } = ctx.THREE;

  // Root container
  const root = new Group();

  // Prepare geometry – use image aspect ratio (512:320 = 1.6)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Material – start without texture, will be filled async
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: false,
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture (if any)
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Event handlers placeholder
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Dispose texture if it was loaded
    if (loadedTexture) {
      loadedTexture.dispose();
    }

    // Kill any GSAP timelines (none in this node but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
